def crt(c_list, n_list):
    N = n_list[0] * n_list[1] * n_list[2]
    result = 0
    for i in range(3):
        ni = n_list[i]
        ai = c_list[i]
        Ni = N // ni
        mi = inverse(Ni, ni)
        result += ai * mi * Ni
    return result % N

c = crt([c1, c2, c3], [n1, n2, n3])

m, exact = integer_nthroot(c, 3)
if exact:
    flag = long_to_bytes(m)
    print("Recovered FLAG:", flag)
else:
    print("Failed to recover exact root.")
